#include <WiFi.h>
#include <WebServer.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;
WebServer server(80);

// ===== Сети: имя и пароль парами =====
const char* WIFI_SSIDS[] = {"KIBERone5", "KIBERone"};
const char* WIFI_PASSS[] = {"KIBERone", "KIBERone"};
const int   WIFI_COUNT   = sizeof(WIFI_SSIDS) / sizeof(WIFI_SSIDS[0]);

void connectWiFi() {
  Serial.println("Сканирую сети...");
  int n = WiFi.scanNetworks();
  if (n <= 0) { Serial.println("Сети не найдены!"); return; }

  for (int i = 0; i < n; i++) {
    String found = WiFi.SSID(i);
    for (int j = 0; j < WIFI_COUNT; j++) {
      if (found == WIFI_SSIDS[j]) {
        Serial.printf("Найдена \"%s\", подключаюсь...\n", WIFI_SSIDS[j]);
        WiFi.begin(WIFI_SSIDS[j], WIFI_PASSS[j]);
        unsigned long start = millis();
        while (WiFi.status() != WL_CONNECTED && millis() - start < 15000) {
          delay(500); Serial.print(".");
        }
        Serial.println();
        if (WiFi.status() == WL_CONNECTED) return;
        Serial.println("Не подключилось, пробую следующую.");
      }
    }
  }
  Serial.println("Ни одна сеть не подключилась.");
}

// ===== Страница-скример =====
const char* PAGE_HTML = R"rawliteral(
<!DOCTYPE html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Подождите...</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;font-family:sans-serif}
  #wait{height:100%;display:flex;flex-direction:column;align-items:center;
        justify-content:center;background:#f5f5f5}
  .spin{width:48px;height:48px;border:5px solid #ccc;border-top-color:#333;
        border-radius:50%;animation:sp 1s linear infinite}
  @keyframes sp{to{transform:rotate(360deg)}}
  #wait p{margin-top:20px;color:#666}
  #boom{display:none;height:100%;background:#000;cursor:default}
