        font-size:min(90vmin,900px);line-height:1;animation:shake .08s infinite}
  @keyframes shake{0%{transform:translate(-52%,-50%) scale(1.05)}
                   50%{transform:translate(-49%,-52%) scale(1.15)}
                   100%{transform:translate(-51%,-49%) scale(1.08)}}
  .flash{animation:fl .15s infinite}
  @keyframes fl{0%,100%{background:#000}50%{background:#a00}}
</style></head><body>

<div id="wait">
  <div class="spin"></div>
  <p>Загрузка обновления... нажмите, чтобы продолжить</p>
</div>

<div id="boom">
  <div id="face">👹</div>
</div>

<script>
const wait = document.getElementById('wait');
const boom = document.getElementById('boom');

// Громкий "крик" на Web Audio: рёв + белый шум
function scream() {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  ctx.resume();

  // Белый шум на максимальной громкости
  const len = ctx.sampleRate * 2.5;
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random()*2-1) * Math.pow(1 - i/len, 0.3);
  const noise = ctx.createBufferSource(); noise.buffer = buf;

  // Рёв: пила с падающей частотой — классический "крик"
  const osc = ctx.createOscillator();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(1800, ctx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(120, ctx.currentTime + 1.5);
  const lfo = ctx.createOscillator(); lfo.frequency.value = 25;
  const lfoGain = ctx.createGain(); lfoGain.gain.value = 300;
  lfo.connect(lfoGain); lfoGain.connect(osc.frequency);

  const g = ctx.createGain();
  g.gain.setValueAtTime(1.0, ctx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.5);

  noise.connect(g); osc.connect(g); g.connect(ctx.destination);
  noise.start(); osc.start(); lfo.start();
  noise.stop(ctx.currentTime + 2.5); osc.stop(ctx.currentTime + 2.5);
}

wait.addEventListener('click', () => {
  // Полный экран, чёрный фон, моргание красным, тряска лица
  if (document.documentElement.requestFullscreen)
    document.documentElement.requestFullscreen().catch(()=>{});
  wait.style.display = 'none';
  boom.style.display = 'block';
  boom.classList.add('flash');
  scream();
  setTimeout(() => boom.classList.remove('flash'), 1200);
});
</script>
