void handleRoot() { server.send(200, "text/html", PAGE_HTML); }

// ===== Автооткрытие сайта как "клавиатура" =====
void openSite(String url) {
  delay(1500);  // окно успевает получить фокус

  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(150);
  Keyboard.releaseAll();
  delay(1200);

  Keyboard.print(url);
  delay(400);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
}

void typeText(String text) {
  for (unsigned int i = 0; i < text.length(); i++) {
    char c = text[i];
    if (c == '\n') { Keyboard.press(KEY_RETURN); Keyboard.releaseAll(); }
    else Keyboard.write(c);
    delay(60);
  }
}

void setup() {
  Serial.begin(115200);

  Keyboard.begin();
  USB.begin();
  delay(3000);   // ждём, пока ПК распознает клавиатуру

  WiFi.mode(WIFI_STA);
  connectWiFi();

  server.on("/", handleRoot);
  server.begin();

  String url = "http://" + WiFi.localIP().toString();

  Serial.println();
  Serial.println("========================================");
  Serial.println("  Скример готов!");
  Serial.print  ("  Сайт: http://");
  Serial.println(WiFi.localIP());
  Serial.println("========================================");

  // Плата печатает адрес в Win+R -> браузер открывает скример
  openSite(url);
}

void loop() {
  server.handleClient();

  // Автопереподключение при обрыве
  if (WiFi.status() != WL_CONNECTED) {
    static unsigned long lastTry = 0;
    if (millis() - lastTry > 30000) { lastTry = millis(); connectWiFi(); }
  }

  delay(10);
}
